<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>WastedToken Mint — Physical Proof of Chaos</title>
<style>
  :root{
    --ink:#090a0d; --paper:#eee8d8; --muted:#a9a28f; --copper:#b9683c;
    --line:rgba(238,232,216,.16); --gold:#d7ae55;
  }
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    margin:0;background:var(--ink);color:var(--paper);
    font-family:Georgia,"Times New Roman",serif;
    letter-spacing:.015em;
  }
  header{
    position:absolute;z-index:5;top:0;left:0;width:100%;
    display:flex;justify-content:space-between;align-items:center;
    padding:26px 5vw;color:var(--paper)
  }
  .brand{font:700 14px/1 Arial,sans-serif;letter-spacing:.22em;text-transform:uppercase}
  .brand b{color:var(--copper)}
  nav{display:flex;gap:28px;font:11px Arial,sans-serif;letter-spacing:.17em;text-transform:uppercase}
  nav a{color:var(--paper);text-decoration:none;opacity:.72}
  nav a:hover{opacity:1;color:#e0a26d}
  .hero{
    min-height:720px;position:relative;overflow:hidden;
    display:grid;grid-template-columns:1fr 1fr;align-items:center;
    padding:90px 5vw 50px;
    background:
      radial-gradient(ellipse at 74% 48%,rgba(190,100,52,.15),transparent 34%),
      radial-gradient(ellipse at 20% 80%,rgba(255,255,255,.045),transparent 33%),
      #090a0d;
  }
  .hero-copy{position:relative;z-index:2;max-width:490px}
  .eyebrow{font:11px Arial,sans-serif;letter-spacing:.3em;text-transform:uppercase;color:#d28a5c;margin-bottom:24px}
  h1{font-size:clamp(46px,6vw,86px);line-height:.88;margin:0 0 28px;font-weight:normal;letter-spacing:-.055em}
  h1 em{font-style:italic;color:#d79a6e}
  .hero-copy p{font-size:18px;line-height:1.65;color:#beb7a6;max-width:400px}
  .hero-link{display:inline-block;margin-top:20px;color:var(--paper);border-bottom:1px solid var(--copper);padding-bottom:8px;text-decoration:none;font:11px Arial,sans-serif;letter-spacing:.18em;text-transform:uppercase}
  #coin-hero{width:100%;height:min(58vw,570px);min-height:390px;display:block}
  .ticker{position:absolute;bottom:24px;left:5vw;right:5vw;border-top:1px solid var(--line);padding-top:13px;color:#746f65;font:10px Arial,sans-serif;letter-spacing:.18em;text-transform:uppercase}
  section{padding:110px 5vw}
