  .about{display:grid;grid-template-columns:.8fr 1.2fr;gap:10vw;max-width:1200px;margin:auto}
  h2{font-size:clamp(38px,5vw,68px);font-weight:normal;line-height:.95;letter-spacing:-.045em;margin:0}
  .about-copy{font-size:19px;line-height:1.7;color:#b6b0a1;max-width:600px}
