  @media(max-width:800px){
    header{padding:20px 6vw}nav{gap:12px}.hero{grid-template-columns:1fr;min-height:900px;padding:120px 6vw 50px}.hero-copy{margin:auto 0}.hero canvas{height:450px}.ticker{left:6vw;right:6vw}
    .about{grid-template-columns:1fr;gap:40px}.collection-head{display:block}.grid{grid-template-columns:repeat(2,1fr)}
  }
  @media(max-width:480px){nav{display:none}.grid{grid-template-columns:1fr}.edition-canvas{height:260px}section{padding:75px 6vw}}
