<body>
<header>
  <div class="brand"><b>WT</b> / WastedToken Mint</div>
  <nav><a href="#about">The mint</a><a href="#collection">Editions</a></nav>
</header>

<main>
  <section class="hero">
    <div class="hero-copy">
      <div class="eyebrow">Object 01 / A physical receipt</div>
      <h1>Make the<br><em>moment</em> count.</h1>
      <p>Challenge coins for the beautifully overcommitted. Struck in honest metal, numbered by hand, and awarded only to people who were there.</p>
      <a class="hero-link" href="#collection">Explore the first strike&nbsp; →</a>
    </div>
    <canvas id="coin-hero" aria-label="Animated WastedToken challenge coin"></canvas>
    <div class="ticker">Individually struck · Serialized · No second chances</div>
  </section>

  <section class="about" id="about">
    <div><div class="section-kicker">About the mint</div><h2>Proof that<br>you showed up.</h2></div>
    <div class="about-copy">
      <p>WastedToken Mint makes <strong>collectible physical challenge coins</strong> for victories too strange for a trophy and too important for a thumbs-up. Every edition is designed in our tiny workshop, then pressed into dense metal with the kind of relief your fingertips can read in the dark.</p>
      <p>We believe the best stories deserve a little weight. Keep one in your pocket. Trade it with someone who understands. Spend it on nothing.</p>
      <div class="rule"></div>
      <div class="stats"><div class="stat"><b>01</b><span>First strike</span></div><div class="stat"><b>10k</b><span>Token denomination</span></div><div class="stat"><b>∞</b><span>Good stories</span></div></div>
    </div>
  </section>

  <section class="collection" id="collection">
    <div class="collection-head"><div><div class="section-kicker">The inaugural run</div><h2>Choose your metal.</h2></div><p>Four finishes / One shared legend</p></div>
    <div class="grid">
      <div class="edition" data-edition="bronze" data-state="available">
        <canvas class="edition-canvas"></canvas><h3>Bronze</h3><small>Warm strike · Edition 001</small><div class="status">Available · $48</div><button class="buy">Add to cart</button>
      </div>
      <div class="edition" data-edition="silver" data-state="available">
        <canvas class="edition-canvas"></canvas><h3>Silver</h3><small>Bright strike · Edition 002</small><div class="status">Available · $72</div><button class="buy">Add to cart</button>
      </div>
      <div class="edition" data-edition="gold" data-state="sold-out">
        <canvas class="edition-canvas"></canvas><h3>Gold</h3><small>Gilded strike · Edition 003</small><div class="status">SOLD OUT</div>
      </div>
      <div class="edition" data-edition="black" data-state="coming-soon">
        <canvas class="edition-canvas"></canvas><h3>Black</h3><small>Obsidian strike · Edition 004</small><div class="status">MINTING NEXT SEASON — AUTUMN</div>
      </div>
    </div>
  </section>
</main>
<footer><span>WastedToken Mint © 2025</span><span>Made for the record</span></footer>

<script>
(() => {
  const hero = document.getElementById('coin-hero');
  const ctx = hero.getContext('2d');
  let raf = 0, paused = false, current = 0;

  function fit(c) {
    const r = c.getBoundingClientRect(), d = Math.min(2, devicePixelRatio || 1);
    const w = Math.max(1, Math.round(r.width*d)), h = Math.max(1, Math.round(r.height*d));
    if(c.width !== w || c.height !== h){c.width=w;c.height=h}
    return [w/d,h/d,d];
  }
  function ellipsePath(c,x,y,rx,ry){
    c.beginPath(); c.ellipse(x,y,Math.max(1,rx),Math.max(1,ry),0,0,Math.PI*2);
  }
  function coin(c,w,h,t,palette,detail=true){
    const d = Math.min(2,devicePixelRatio||1);
    c.save(); c.scale(d,d);
    w/=d;h/=d;
    c.clearRect(0,0,w,h);
    c.fillStyle = palette.bg || '#090a0d'; c.fillRect(0,0,w,h);
    const yaw=t*Math.PI*2, pitch=t*Math.PI*2;
    const nx=Math.sin(yaw)*Math.cos(pitch), ny=-Math.sin(pitch), nz=Math.cos(yaw)*Math.cos(pitch);
    const wf=Math.sqrt(Math.max(.035,1-nx*nx)), hf=Math.sqrt(Math.max(.07,1-ny*ny));
    const R=Math.min(w*.34,h*.42), cx=w*.5, cy=h*.5;
    const rx=R*wf, ry=R*hf, side=R*.075;
    c.save();
    c.shadowColor='rgba(0,0,0,.7)';c.shadowBlur=28;c.shadowOffsetY=18;
    ellipsePath(c,cx,cy,rx+side,ry+side*.55);c.fillStyle='#030405';c.fill();c.restore();
    // thick metal rim
    let rim=c.createLinearGradient(cx-rx,cy,cx+rx,cy);
    rim.addColorStop(0,palette.dark);rim.addColorStop(.25,palette.mid);rim.addColorStop(.52,palette.light);rim.addColorStop(.75,palette.mid);rim.addColorStop(1,palette.dark);
    ellipsePath(c,cx,cy,rx+side,ry+side*.55);c.fillStyle=rim;c.fill();
    // reeded edge, always readable as the coin turns
    c.save(); ellipsePath(c,cx,cy,rx+side*.72,ry+side*.38);c.clip();
    c.strokeStyle=palette.ridge;c.lineWidth=1;
    for(let i=-18;i<19;i++){
      const yy=cy+i*2.8;
      c.beginPath();c.moveTo(cx-rx-side,yy);c.lineTo(cx+rx+side,yy+7);c.stroke();
    }
    c.restore();
    // face
    const front=nz>=0;
    ellipsePath(c,cx,cy,rx,ry);
    let face=c.createRadialGradient(cx-rx*.38,cy-ry*.5,2,cx+rx*.5,cy+ry*.65,R*1.4);
    face.addColorStop(0,palette.shine);face.addColorStop(.22,palette.light);face.addColorStop(.56,palette.mid);face.addColorStop(1,palette.dark);
    c.fillStyle=face;c.fill();
    c.save();ellipsePath(c,cx,cy,rx,ry);c.clip();
    // machined rings
    for(let k=0;k<4;k++){c.beginPath();c.ellipse(cx,cy,rx-k*5,ry-k*4,0,0,Math.PI*2);c.strokeStyle='rgba(255,255,255,'+(k===0?.22:.08)+')';c.lineWidth=1;c.stroke()}
    // moving specular rake
    const sx=cx+Math.cos(yaw*1.7+.6)*rx*.62;
    const sg=c.createLinearGradient(sx-rx*.22,cy-ry,sx+rx*.22,cy+ry);
    sg.addColorStop(0,'rgba(255,255,255,0)');sg.addColorStop(.48,'rgba(255,255,255,.48)');sg.addColorStop(.54,'rgba(255,255,255,.12)');sg.addColorStop(1,'rgba(255,255,255,0)');
    c.fillStyle=sg;c.fillRect(cx-rx,cy-ry,rx*2,ry*2);
    // raised artwork
    c.translate(cx,cy); c.scale(1,Math.max(.08,hf));
    c.rotate((pitch>Math.PI/2&&pitch<Math.PI*1.5)?Math.PI:0);
    if(front){
      // relief shadows then highlights
      c.font='bold 45px Georgia';c.textAlign='center';c.textBaseline='middle';
      c.fillStyle='rgba(20,10,5,.62)';c.fillText('W',3,5);
      c.fillStyle=palette.emboss;c.fillText('W',0,1);
      c.strokeStyle=palette.emboss;c.lineWidth=2;c.beginPath();c.arc(0,0,58,0,Math.PI*2);c.stroke();
      c.font='bold 9px Arial';c.letterSpacing='3px';c.fillStyle=palette.emboss;c.fillText('WASTEDTOKEN',0,-42);c.fillText('MINT',0,42);
      c.beginPath();c.moveTo(-36,-21);c.lineTo(36,-21);c.moveTo(-36,21);c.lineTo(36,21);c.stroke();
    }else{
      c.textAlign='center';c.textBaseline='middle';c.font='bold 25px Arial';
      c.fillStyle='rgba(15,15,15,.7)';c.fillText('10,000',2,3);
      c.fillStyle=palette.emboss;c.fillText('10,000',0,0);
      c.font='bold 10px Arial';c.fillText('TOKENS',0,27);
      c.strokeStyle=palette.emboss;c.lineWidth=2;c.beginPath();c.arc(0,0,58,0,Math.PI*2);c.stroke();
      c.font='9px Arial';c.fillText('LEGAL TENDER FOR GREAT STORIES',0,-31);
    }
    c.restore();
    // outer engraved border
    ellipsePath(c,cx,cy,rx-4,ry-4);c.strokeStyle='rgba(255,235,190,.55)';c.lineWidth=1.4;c.stroke();
    ellipsePath(c,cx,cy,rx+side*.35,ry+side*.18);c.strokeStyle='rgba(0,0,0,.7)';c.lineWidth=2;c.stroke();
    c.restore();
  }

  function renderHero(t){const [w,h]=fit(hero);coin(ctx,w,h,t,{bg:'#090a0d',dark:'#4c2417',mid:'#a95832',light:'#d59262',shine:'#ffe0ad',ridge:'#d18a5e',emboss:'#f0bc8b'});current=t}
  function loop(){if(!paused){renderHero((performance.now()/9000)%1);raf=requestAnimationFrame(loop)}}
  window.demo={canvas:hero,setTime(t){paused=true;renderHero(Math.max(0,Math.min(1,t)))},pause(){paused=true;cancelAnimationFrame(raf)}};
  renderHero(0); loop();

  const colors={
    bronze:{dark:'#4c2417',mid:'#a95832',light:'#d59262',shine:'#ffe0ad',ridge:'#d18a5e',emboss:'#f0bc8b'},
    silver:{dark:'#4b5359',mid:'#aebbc0',light:'#eef4ed',shine:'#ffffff',ridge:'#dce5e2',emboss:'#ffffff'},
    gold:{dark:'#644b19',mid:'#c18e2e',light:'#f1cf6a',shine:'#fff0a9',ridge:'#e7c35f',emboss:'#ffe8a0'},
    black:{dark:'#101318',mid:'#343b45',light:'#727b87',shine:'#d5e1eb',ridge:'#8f9aa6',emboss:'#d4dee5'}
  };
  document.querySelectorAll('.edition').forEach((el,i)=>{
    const c=el.querySelector('canvas'), x=c.getContext('2d'), key=el.dataset.edition;
    function draw(){const [w,h]=fit(c);coin(x,w,h,(i+1)*.11, {...colors[key],bg:'#15161a'}); }
    new ResizeObserver(draw).observe(c); draw();
  });
})();
</script>
</body>
</html>
